    Lemma loop : forall (fuel : nat) (Fx : bvmap 5 word) (fcx : bv 32) msF mo sx psx XS mc kvl (q lo1 : Z)
                        (xra x5 x6 x7 xa0 xa2 xa3 xa4 xa5 xa6 xa7 x28 x29 x30 x31 : word),
      let i := Z.of_nat (length kvl) in
      (Z.to_nat (e - q) <= fuel)%nat ->
      as_AKREL H sx (mkCfg msF mo) -> as_MPRES H mo0 mo -> frm0 fcx ->
      as_VIS H sx msF = MS (mkR xra (wz sp') gp tp x5 x6 x7 a0 (Z_to_bv 64 4294977024) xa0 (Z_to_bv 64 q) xa2 xa3 xa4 xa5 xa6 xa7
                               (wz 0) (Z_to_bv 64 (-1)) (wz 0) (Z_to_bv 64 i) (Z_to_bv 64 1) (Z_to_bv 64 2147450880) (Z_to_bv 64 e) (Z_to_bv 64 32) (Z_to_bv 64 (pa + 1)) (Z_to_bv 64 2147483646) x28 x29 x30 x31)
                          Fx (Z_to_bv 64 APO_LOOP) fcx None mc (seg_rom asegs) ->
      cst sx psx XS mc -> psK psx kvl -> 1 <= d -> stk asegs mc lo sp' ->
      rw_cells asegs mc sp' (apo_fr1 (Z_to_bv 64 ((pa + 264) ≫ 3 + 2147450880)) (Z_to_bv 64 (pa + 264)) (wz 0) s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
      p < q < e -> bv_unsigned (inpb q) = 34 -> vs_n (ps_vs psx) + (e - q) < 2^26 ->
      pots_le (ps_vs psx) (e - q) st0 (e - p) (-32 * (2 * i + 1)) (-(2 * i + 1)) (-40) (-256) -> vs_capshape (ps_vs psx) ->
      pv_spent H st0 (e - p) lo1 (as_AL H s) (as_AL H sx) -> rc_al (ps_vs psx) (e - q) + 256 <= lo1 ->
      as_SR H POST (mkCfg msF mo).
Proof.
